205	func (s *APIV1Service) DeleteUserWebhook(ctx context.Context, request *v1pb.DeleteUserWebhookRequest) (*emptypb.Empty, error) {
206		user, webhookID, err := s.resolveUserAndWebhookIDFromName(ctx, request.Name)
207		if err != nil {
208			return nil, status.Errorf(codes.InvalidArgument, "invalid webhook name: %v", err)
209		}
210		userID := user.ID
211	
212		currentUser, err := s.fetchCurrentUser(ctx)
213		if err != nil {
214			return nil, status.Errorf(codes.Internal, "failed to get current user: %v", err)
215		}
216		if currentUser == nil {
217			return nil, status.Errorf(codes.Unauthenticated, "user not authenticated")
218		}
219		if currentUser.ID != userID && currentUser.Role != store.RoleAdmin {
220			return nil, status.Errorf(codes.PermissionDenied, "permission denied")
221		}
222	
223		// Get existing webhooks to verify the webhook exists
224		webhooks, err := s.Store.GetUserWebhooks(ctx, userID)
225		if err != nil {
226			return nil, status.Errorf(codes.Internal, "failed to get user webhooks: %v", err)
227		}
228	
229		// Check if webhook exists
230		found := false
231		for _, webhook := range webhooks {
232			if webhook.Id == webhookID {
233				found = true
234				break
235			}
236		}
237	
238		if !found {
239			return nil, status.Errorf(codes.NotFound, "webhook not found")
240		}
241	
242		err = s.Store.RemoveUserWebhook(ctx, userID, webhookID)
243		if err != nil {
244			return nil, status.Errorf(codes.Internal, "failed to delete webhook: %v", err)
245		}
246	
247		return &emptypb.Empty{}, nil
248	}
