278	// Helper functions for webhook operations
279	
280	// generateUserWebhookID generates a unique ID for user webhooks.
281	func generateUserWebhookID() string {
282		b := make([]byte, 8)
283		rand.Read(b)
284		return hex.EncodeToString(b)
285	}
286	
287	// convertUserWebhookFromUserSetting converts a storepb webhook to a v1pb UserWebhook.
288	func convertUserWebhookFromUserSetting(webhook *storepb.WebhooksUserSetting_Webhook, user *store.User) *v1pb.UserWebhook {
289		return &v1pb.UserWebhook{
290			Name:             fmt.Sprintf("%s/webhooks/%s", BuildUserName(user.Username), webhook.Id),
291			Url:              webhook.Url,
292			DisplayName:      webhook.Title,
293			SigningSecretSet: webhook.SigningSecret != "",
294			// Note: create_time and update_time are not available in the user setting webhook structure
295			// This is a limitation of storing webhooks in user settings vs the dedicated webhook table
296		}
297	}
